-- 010 확인용 — 2026-10-07 피싱 이름 목록(services/blacklist.js)이 «기존» 이름 중 몇 개를 잡았을지.
-- 읽기 전용. 아무것도 바꾸지 않는다. 기존 레코드는 새 규칙의 대상이 아니다(생성 때만 검사) —
-- 이 숫자는 «목록이 너무 넓은가»를 판단하는 근거다. 목록을 고치면 이 파일도 다시 만든다:
--   node -e 'const b=require("./services/blacklist");console.log(b.BRAND_KEYWORDS.join("|"),b.ANON_KEYWORDS.join("|"))'
-- brand_all = 누구든 새로 만들 수 없게 된 이름 · word_anon = 익명이 가진 일반어 이름 · word_account = 계정이 가진 일반어 이름(계정은 계속 허용)
-- 실행: mysql -u <user> -p <db> < scripts/010-blacklist-hits.sql
SELECT COUNT(*) AS total, SUM(subdomain REGEXP 'paypal|google-login|facebook-auth|bank|secure-login|signin|account-verify|toss|kakao|naver|upbit|bithumb|coinbase|binance|metamask|apple|icloud|microsoft|office365|outlook|amazon|netflix|instagram|whatsapp|telegram|hometax|shinhan|kbstar|wooribank|hanabank|kakaobank|nhbank|coupang') AS brand_all, SUM(owner_type = 'agent' AND subdomain REGEXP 'login|signin|verify|wallet|password|recovery|support|security|account|auth|bank' AND NOT subdomain REGEXP 'paypal|google-login|facebook-auth|bank|secure-login|signin|account-verify|toss|kakao|naver|upbit|bithumb|coinbase|binance|metamask|apple|icloud|microsoft|office365|outlook|amazon|netflix|instagram|whatsapp|telegram|hometax|shinhan|kbstar|wooribank|hanabank|kakaobank|nhbank|coupang') AS word_anon, SUM(owner_type = 'user' AND subdomain REGEXP 'login|signin|verify|wallet|password|recovery|support|security|account|auth|bank' AND NOT subdomain REGEXP 'paypal|google-login|facebook-auth|bank|secure-login|signin|account-verify|toss|kakao|naver|upbit|bithumb|coinbase|binance|metamask|apple|icloud|microsoft|office365|outlook|amazon|netflix|instagram|whatsapp|telegram|hometax|shinhan|kbstar|wooribank|hanabank|kakaobank|nhbank|coupang') AS word_account FROM subdomains;
-- 이름까지 보려면(같은 조건):
-- SELECT subdomain, owner_type, created_at FROM subdomains WHERE subdomain REGEXP 'paypal|google-login|facebook-auth|bank|secure-login|signin|account-verify|toss|kakao|naver|upbit|bithumb|coinbase|binance|metamask|apple|icloud|microsoft|office365|outlook|amazon|netflix|instagram|whatsapp|telegram|hometax|shinhan|kbstar|wooribank|hanabank|kakaobank|nhbank|coupang|login|signin|verify|wallet|password|recovery|support|security|account|auth|bank' ORDER BY created_at;
